def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    # Fill missing background cells along the object's bounding-box perimeter.
    for r in (r0, r1):
        for c in range(c0, c1+1):
            if grid[r][c] == bg: out[r][c] = 2
    for c in (c0, c1):
        for r in range(r0, r1+1):
            if grid[r][c] == bg: out[r][c] = 2
    return out
